begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('91000000-0000-4000-8000-000000000001'),('91000000-0000-4000-8000-000000000002');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('public.profile_image_assets'::regclass,'public.profile_image_copies'::regclass,'public.profile_image_settings'::regclass)),'profile tables force RLS');
select ok(not has_function_privilege('authenticated','public.commit_profile_images(uuid,bigint,uuid,uuid,uuid,uuid,integer)','execute'),'client cannot commit privileged image settings');
select ok(not has_function_privilege('authenticated','public.public_profile_image_record(uuid)','execute'),'object path resolver is service-only');
select ok(not has_function_privilege('anon','public.my_profile_images()','execute'),'anonymous cannot inspect private settings');
select ok(not exists(select 1 from storage.buckets where id in ('deardaily-private','deardaily-story-media') and public),'existing photo buckets remain private');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.my_profile_images()->>'version','0','new user starts without photos');
select lives_ok($$insert into public.public_profiles(username,display_name,avatar,visible) values('synthetic_photo_a','Synthetic A','leaf',true)$$,'A profile fixture');
select lives_ok($$select public.reserve_profile_image('92000000-0000-4000-8000-000000000001','avatar',1024)$$,'owner can reserve avatar');
select throws_ok($$select public.reserve_profile_image(gen_random_uuid(),'svg',1024)$$,'23514',null,'invalid slot rejected');
select throws_ok($$select public.reserve_profile_image(gen_random_uuid(),'avatar',2097153)$$,'23514',null,'oversized image rejected');
select throws_ok($$select * from public.profile_image_assets$$,'42501',null,'raw private image table not exposed');
select throws_ok($$insert into public.profile_image_settings(user_id) values(auth.uid())$$,'42501',null,'client cannot write settings directly');
select throws_ok($$select * from public.profile_image_copies$$,'42501',null,'raw public copy table not exposed');
reset role;
update public.profile_image_assets set status='ready',width=512,height=512 where id='92000000-0000-4000-8000-000000000001';
select lives_ok($$select public.commit_profile_images('91000000-0000-4000-8000-000000000001',0,'92000000-0000-4000-8000-000000000001',null,null,null,70)$$,'save private avatar without publication');
set local role anon;
select is(public.public_profile_images('synthetic_photo_a')->>'avatar',null,'visible profile does not publish private upload automatically');
select throws_ok($$select public.reserve_profile_image(gen_random_uuid(),'avatar',100)$$,'42501',null,'anonymous upload denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.my_profile_images()->>'avatar_asset',null,'B cannot see A private ID');
select throws_ok($$delete from public.profile_image_assets where id='92000000-0000-4000-8000-000000000001'$$,'42501',null,'B cannot delete A image');
select throws_ok($$select public.reserve_profile_image_copy(auth.uid(),'92000000-0000-4000-8000-000000000001',gen_random_uuid())$$,'42501',null,'B cannot stage public copies through service RPC');
select lives_ok($$select public.prune_profile_images()$$,'B cleanup is limited to B');
reset role;
select throws_ok($$select public.commit_profile_images('91000000-0000-4000-8000-000000000002',0,'92000000-0000-4000-8000-000000000001',null,null,null,50)$$,'42501',null,'even trusted commit rejects cross-owner asset');
select throws_ok($$select public.commit_profile_images('91000000-0000-4000-8000-000000000001',1,null,'92000000-0000-4000-8000-000000000001',null,null,50)$$,'42501',null,'avatar cannot be spoofed as banner');
select lives_ok($$select public.reserve_profile_image_copy('91000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001')$$,'stage independently named copy');
select is(public.public_profile_image_record('93000000-0000-4000-8000-000000000001'),null,'staged copy is not public before consent commit');
select lives_ok($$select public.commit_profile_images('91000000-0000-4000-8000-000000000001',1,'92000000-0000-4000-8000-000000000001',null,'93000000-0000-4000-8000-000000000001',null,70)$$,'explicit public consent activates copy');
select throws_ok($$select public.commit_profile_images('91000000-0000-4000-8000-000000000001',1,null,null,null,null,50)$$,'40001',null,'stale update cannot overwrite newer photo');
select throws_ok($$select public.commit_profile_images('91000000-0000-4000-8000-000000000001',2,null,null,null,null,101)$$,'23514',null,'invalid position rejected');
set local role anon;
select is(public.public_profile_images('synthetic_photo_a')->>'avatar','93000000-0000-4000-8000-000000000001','anonymous can read only approved public ID');
select ok(not(public.public_profile_images('synthetic_photo_a') ? 'user_id') and not(public.public_profile_images('synthetic_photo_a') ? 'avatar_asset') and not(public.public_profile_images('synthetic_photo_a') ? 'object_key'),'public response hides owners, private IDs and paths');
reset role;
select is(public.public_profile_image_record('93000000-0000-4000-8000-000000000001'),'profile/93000000-0000-4000-8000-000000000001.webp','service resolves only approved copy');
update public.public_profiles set visible=false where username='synthetic_photo_a';
select is(public.public_profile_images('synthetic_photo_a'),null,'hidden profile has no public photos');
select is(public.public_profile_image_record('93000000-0000-4000-8000-000000000001'),null,'old public ID revoked on hide');
select is((select count(*) from public.profile_image_copies),0::bigint,'hidden public copy queued for removal');
select is((select count(*) from public.profile_image_assets),1::bigint,'hiding preserves private original');
select is((select count(*) from public.media_gc where object_key='profile/93000000-0000-4000-8000-000000000001.webp'),1::bigint,'exact old copy queued');
update public.public_profiles set visible=true where username='synthetic_photo_a';
select is(public.public_profile_images('synthetic_photo_a')->>'avatar',null,'unhiding never republishes images automatically');
select lives_ok($$select public.commit_profile_images('91000000-0000-4000-8000-000000000001',3,null,null,null,null,50)$$,'remove avatar restores default icon');
update public.profile_image_assets set created_at=now()-interval '2 hours';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.prune_profile_images(),0,'B cannot prune A replaced original');
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.prune_profile_images(),1,'A can prune unreferenced original after grace');
reset role;
select is((select count(*) from public.profile_image_assets),0::bigint,'old original metadata removed');
select is((select count(*) from public.media_gc where object_key='profile/91000000-0000-4000-8000-000000000001/92000000-0000-4000-8000-000000000001.webp'),1::bigint,'private original queues its exact key');
select * from finish();
rollback;
